// Function for verifying results
bool verify(std::vector<float, aligned_allocator<float>> &sw_out,
            std::vector<float, aligned_allocator<float>> &hw_out,
            unsigned int size) 
{
    bool check = true;
    int num_err = 0;
    for (unsigned int i=0; i<size; ++i) {
        if (sw_out[i] != hw_out[i]) {
            check = false;
